update_md5_40a88ba81a3794429b4f8a2292b72.content_md5_40a88ba81a3794429b4f8a2292b7:
procedure TRagManagerForm.FreeRagAndItems;
var
  i: Integer;
begin
  if not Assigned(FRag) then
    Exit;
  try
    for i := 0 to FRag.Items.Count - 1 do
      FRag.Items[i].Free;
  except
    // ignore cleanup errors
  end;
  FreeAndNil(FRag);
end;

procedure TRagManagerForm.ResetRag;
begin
  FreeRagAndItems;
  FRag := TAiRAGVector.Create(Self);
  FRag.Embeddings := FEmbeddings;
end;

update_md5_ffe0c0b7c07ea1babf9a9eab756f4.find_text:
procedure TRagManagerForm.LoadJson(const Path: string);
begin
  FRag.Clear;
  FRag.LoadFromFile(Path);
  SetStatus(Format('Loaded %d item(s) from %s (dim=%d)', [FRag.Count, Path, FRag.Dim]));
end;

update_md5_ffe0c0b7c07ea1babf9a9eab756f4.content_md5_ffe0c0b7c07ea1babf9a9eab756f:
procedure TRagManagerForm.LoadJson(const Path: string);
begin
  ResetRag;
  FRag.LoadFromFile(Path);
  SetStatus(Format('Loaded %d item(s) from %s (dim=%d)', [FRag.Count, Path, FRag.Dim]));
end;

