    if Assigned(node) then
    begin
      if not Assigned(node.jData) then
        node.jData := TJSONObject.Create;
      node.jData.AddPair('path', InputBox('Add item', 'Path (json.path):', ''));
      node.jData.AddPair('meta', '');
