update_md5_18844966c269d3a630615f2635453.find_text:
procedure TRagManagerForm.OnDeleteClick(Sender: TObject);
var
  idx: Integer;
begin
  idx := ListItems.ItemIndex;
  if (idx < 0) or (idx >= FRag.Items.Count) then Exit;
  if MessageDlg('Delete selected item?', mtConfirmation, [mbYes, mbNo], 0) <> mrYes then
    Exit;
  FRag.Items[idx].Free;
  FRag.Items.Delete(idx);
  RefreshList;
  MemoText.Clear;
  MemoMeta.Clear;
  EdPath.Text := '';
end;

update_md5_18844966c269d3a630615f2635453.content_md5_18844966c269d3a630615f263545:
procedure TRagManagerForm.OnDeleteClick(Sender: TObject);
var
  idx: Integer;
  node: TAiEmbeddingNode;
begin
  if FJsonPath = '' then
  begin
    SetStatus('No JSON path loaded; cannot delete safely.');
    Exit;
  end;

  idx := ListItems.ItemIndex;
  if (idx < 0) or (idx >= FRag.Items.Count) then Exit;
  if MessageDlg('Delete selected item?', mtConfirmation, [mbYes, mbNo], 0) <> mrYes then
    Exit;

  node := FRag.Items[idx];
  FRag.Items.Delete(idx);
  SaveJson(FJsonPath);

  // ResetRag inside LoadJson frees the old in-memory index state. Free the removed node afterwards.
  LoadJson(FJsonPath);
  node.Free;

  RefreshList;
  MemoText.Clear;
  MemoMeta.Clear;
  EdPath.Text := '';
end;
